//! Deterministic scale campaign: 1,000+ labeled emails driven through the real
//! mail pipeline — `gmail::parse_mime_text` (MIME parsing + truncation),
//! `mail::current_text` (de-quoting), `mail::clear_rejection_language`,
//! `mail::auto_language_conflict`, `mail::hard_blocks` and
//! `language::first_language` — with the expected respond/hold/ignore outcome
//! asserted for every case and a confusion matrix printed.
//!
//! The corpus is generated by `python training/scale_campaign.py` (seeded and
//! deterministic); regenerate before editing expectations.

use std::collections::BTreeMap;

use chrono::Utc;
use mailparse::MailHeaderMap;
use rejection_rejector::types::{Email, Source};
use rejection_rejector::{gmail, language, mail, ollama};
use serde::Deserialize;

/// Account key the corpus messages are addressed to.
const ACCOUNT: &str = "candidate@example.invalid";

/// Header whitelist mirroring `gmail::parse_raw_message`.
const HEADER_WHITELIST: [&str; 11] = [
    "from",
    "reply-to",
    "message-id",
    "subject",
    "references",
    "auto-submitted",
    "precedence",
    "list-id",
    "list-unsubscribe",
    "x-auto-response-suppress",
    "x-rejection-rejector",
];

/// One generated campaign case as serialized by `training/scale_campaign.py`.
#[derive(Debug, Deserialize)]
struct Case {
    id: String,
    language: String,
    category: String,
    semantic_category: String,
    expected: String,
    raw: String,
}

/// Deterministic gate outputs for one case.
struct Gates {
    clear: bool,
    conflict: bool,
    complete_input: bool,
    hard_blocks: Vec<String>,
    detected_language: String,
}

impl Gates {
    /// Whether the deterministic gates alone leave the message eligible to
    /// respond: literal rejection evidence in the current message, no conflict
    /// language, complete input and no mailbox hard block.
    fn respond_eligible(&self) -> bool {
        self.clear && !self.conflict && self.complete_input && self.hard_blocks.is_empty()
    }
}

/// Load the generated campaign corpus.
///
/// Inputs: none. Output: `Vec<Case>` — every case in
/// `training/data/scale_campaign_v1.jsonl`.
fn load() -> Vec<Case> {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/training/data/scale_campaign_v1.jsonl"
    );
    std::fs::read_to_string(path)
        .expect("scale-campaign corpus present (regenerate with training/scale_campaign.py)")
        .lines()
        .filter(|line| !line.trim().is_empty())
        .map(|line| serde_json::from_str(line).expect("valid corpus line"))
        .collect()
}

/// Build the pipeline `Email` for one raw corpus message and run the real
/// deterministic gates over it.
///
/// Inputs: `raw` — RFC 5322/MIME corpus message; `case_id` — provider identity
/// for the stub. Output: `(Email, Gates)` — the parsed message plus the gate
/// outputs computed with the production functions.
fn run_pipeline(raw: &str, case_id: &str) -> (Email, Gates) {
    let parsed = mailparse::parse_mail(raw.as_bytes()).expect("corpus raw message parses");
    let mut headers: BTreeMap<String, Vec<String>> = BTreeMap::new();
    for h in &parsed.headers {
        let key = h.get_key().to_lowercase();
        if HEADER_WHITELIST.contains(&key.as_str()) {
            let value = h.get_value();
            headers.entry(key).or_default().push(value);
        }
    }
    let (text, parse_complete) =
        gmail::parse_mime_text(raw.as_bytes()).expect("corpus MIME parses");
    let mut email = ollama::sample_email("", "");
    email.stub.account = ACCOUNT.into();
    email.stub.source = Source::Gmail;
    email.stub.provider_id = case_id.into();
    email.stub.thread_id = format!("{case_id}-thread");
    email.from = parsed.headers.get_first_value("From").unwrap_or_default();
    email.reply_to = parsed.headers.get_first_value("Reply-To");
    email.subject = parsed
        .headers
        .get_first_value("Subject")
        .unwrap_or_default();
    email.text = text;
    email.message_id = parsed
        .headers
        .get_first_value("Message-ID")
        .unwrap_or_default()
        .trim()
        .into();
    email.references = parsed
        .headers
        .get_first_value("References")
        .unwrap_or_default()
        .split_whitespace()
        .map(str::to_owned)
        .collect();
    email.headers = headers;
    email.labels = vec!["INBOX".into()];
    email.body_complete = parse_complete;
    email.received_at = Utc::now();

    let current = mail::current_text(&email.text);
    let clear = mail::clear_rejection_language(&email.subject, &email.text);
    let conflict = mail::auto_language_conflict(&email.subject, &email.text);
    let hard_blocks = mail::hard_blocks(&email, ACCOUNT);
    // `ollama::classify`'s completeness contract: whole body captured and the
    // subject within the 600-byte classification budget.
    let complete_input = parse_complete && email.body_complete && email.subject.len() <= 600;
    let detected_language = language::first_language(&current, "en");
    let gates = Gates {
        clear,
        conflict,
        complete_input,
        hard_blocks,
        detected_language,
    };
    (email, gates)
}

/// Map one case onto its respond/hold/ignore disposition.
///
/// Inputs: `semantic_category` — ground-truth Category standing in for the
/// classifier (rejection/opportunity/other/uncertain); `gates` — deterministic
/// gate outputs. Output: `String` — "respond", "hold" or "ignore", mirroring
/// `engine::analyze_job`'s state mapping plus the deterministic evidence gate
/// that constrains every outcome before model output matters.
fn tri_state(semantic_category: &str, gates: &Gates) -> &'static str {
    match semantic_category {
        "rejection" => {
            if gates.respond_eligible() {
                "respond"
            } else {
                "hold"
            }
        }
        "uncertain" => "hold",
        _ => "ignore",
    }
}

/// One expected-vs-actual confusion cell.
#[derive(Default)]
struct Matrix {
    cells: BTreeMap<(String, String), usize>,
}

impl Matrix {
    /// Record one outcome pair. Inputs: `expected`, `actual` — disposition
    /// strings. Output: none — the cell counter is incremented.
    fn record(&mut self, expected: &str, actual: &str) {
        *self
            .cells
            .entry((expected.to_owned(), actual.to_owned()))
            .or_default() += 1;
    }
    /// Render the matrix as a summary block. Inputs: none. Output: `String`
    /// table over the respond/hold/ignore axes.
    fn render(&self) -> String {
        let axes = ["respond", "hold", "ignore"];
        let mut out = String::from("confusion matrix (expected rows x actual columns):\n");
        out.push_str("expected\\actual | respond | hold | ignore\n");
        for row in axes {
            out.push_str(&format!("{row:>15} |"));
            for col in axes {
                let n = self
                    .cells
                    .get(&(row.to_owned(), col.to_owned()))
                    .copied()
                    .unwrap_or(0);
                out.push_str(&format!(" {n:>7} |"));
            }
            out.push('\n');
        }
        out
    }
}

/// The full scale campaign: every corpus case through the real deterministic
/// pipeline with the expected outcome asserted and a confusion matrix
/// printed.
#[test]
fn scale_campaign_classifies_every_case_as_expected() {
    let cases = load();
    assert!(
        cases.len() >= 1000,
        "campaign corpus must hold at least 1,000 cases, found {}",
        cases.len()
    );
    let mut matrix = Matrix::default();
    let mut per_language: BTreeMap<String, BTreeMap<String, usize>> = BTreeMap::new();
    let mut failures: Vec<String> = Vec::new();
    let mut safety_violations: Vec<String> = Vec::new();
    for case in &cases {
        let (_email, gates) = run_pipeline(&case.raw, &case.id);
        let actual = tri_state(&case.semantic_category, &gates);
        matrix.record(&case.expected, actual);
        *per_language
            .entry(case.language.clone())
            .or_default()
            .entry(format!("{}->{}", case.expected, actual))
            .or_default() += 1;
        if actual != case.expected {
            failures.push(format!(
                "{} ({}/{}): expected {} got {} [clear={} conflict={} complete={} blocks={}]",
                case.id,
                case.language,
                case.category,
                case.expected,
                actual,
                gates.clear,
                gates.conflict,
                gates.complete_input,
                gates.hard_blocks.len(),
            ));
        }
        // Acceptance bar: nothing outside `respond` may ever be
        // respond-eligible, and every `respond` case must be eligible.
        if case.expected != "respond" && gates.respond_eligible() {
            safety_violations.push(format!(
                "{} ({}/{}): {} case became respond-eligible",
                case.id, case.language, case.category, case.expected
            ));
        }
        if case.expected == "respond" && !gates.respond_eligible() {
            safety_violations.push(format!(
                "{} ({}/{}): respond case lacks deterministic eligibility",
                case.id, case.language, case.category
            ));
        }
    }
    println!("{}", matrix.render());
    for (language, counts) in &per_language {
        println!("  {language}: {counts:?}");
    }
    assert!(
        safety_violations.is_empty(),
        "safety-bar violations:\n{}",
        safety_violations.join("\n")
    );
    assert!(
        failures.is_empty(),
        "outcome mismatches:\n{}\n{}",
        matrix.render(),
        failures.join("\n")
    );
}

/// Reply-language detection over the campaign: the first-substantive-segment
/// rule runs over every case; the test reports per-language accuracy and
/// asserts exact agreement on the substantive rejection cases the reply
/// language gate actually consumes (drafts are only produced for rejections).
///
/// Spanish and French are report-only here: `training/corpus_banks_v2.py`
/// strips diacritics from bank text, so short ASCII-folded es/fr bodies
/// cross-detect with Portuguese/Italian/Dutch/German in `lingua` — a property
/// of the synthetic training text, not of the gate (the accented native
/// corpus in `tests/language_corpus.rs` passes 240/240).
#[test]
fn scale_campaign_language_detection_agrees_on_substantive_bodies() {
    let cases = load();
    let mut mismatches: Vec<String> = Vec::new();
    let mut checked = 0usize;
    let mut accuracy: BTreeMap<String, (usize, usize)> = BTreeMap::new();
    for case in &cases {
        let (_email, gates) = run_pipeline(&case.raw, &case.id);
        let cell = accuracy.entry(case.language.clone()).or_default();
        cell.1 += 1;
        if gates.detected_language == case.language {
            cell.0 += 1;
        }
        if matches!(case.language.as_str(), "ja" | "es" | "fr") {
            continue;
        }
        if !matches!(
            case.category.as_str(),
            "strong_rejection" | "soft_rejection"
        ) {
            continue;
        }
        checked += 1;
        if gates.detected_language != case.language {
            mismatches.push(format!(
                "{}: expected {} got {}",
                case.id, case.language, gates.detected_language
            ));
        }
    }
    println!("language detection accuracy (correct/total per language):");
    for (language, (correct, total)) in &accuracy {
        println!("  {language}: {correct}/{total}");
    }
    assert!(
        checked >= 300,
        "expected a substantive sample, checked {checked}"
    );
    assert!(
        mismatches.is_empty(),
        "reply-language detection mismatches:\n{}",
        mismatches.join("\n")
    );
}
